"""Assembles the appendices in the order of the main text (Sec. II -> X), from the files generated by make_split.py.

Called at the end of make_split.py. Reads ../sections/{appendix,appendix_ext,theory,details,appendix_checks,ml,
limitations,code,notation}.tex and writes the new ../sections/appendix.tex; the other files stay as they are.
Every block is used exactly once; unused blocks are listed at the end (nothing is lost silently).
"""
import re, os
DST = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'sections'))
rd = lambda n: open(f'{DST}/{n}.tex').read()
SUB = re.compile(r'(?m)^(?=\\subsection\{)')
SEC = re.compile(r'(?m)^(?=\\section\{)')
FLT = re.compile(r'\\begin\{(figure\*?|table\*?)\}.*?\\end\{\1\}\n?', re.S)


def subs(text):
    """list of (title, block) for the subsections of a text (preamble dropped)."""
    out = []
    for p in SUB.split(text)[1:]:
        m = re.match(r'\\subsection\{(.*)\}', p)
        out.append((m.group(1), p.rstrip() + '\n'))
    return out


def retitle(block, new):
    return re.sub(r'\\subsection\{.*\}', lambda m: '\\subsection{%s}' % new, block, count=1)


def clean(block):
    b = block.rstrip()
    b = re.sub(r'(\\clearpage|\\FloatBarrier)\s*$', '', b).rstrip()
    return b + '\n'


used = set()
POOL = {}   # source -> list of (title, block)


def load(src, text):
    POOL[src] = subs(text)


# ---- sources
ext = rd('appendix_ext')
for sec in SEC.split(ext):
    m = re.search(r'\\label\{(app:ext_[a-z]+)\}', sec)
    if m:
        load(m.group(1), sec)
        # tail "Float(s) Cited in the Main Text" is kept as a float list, not as a subsection
        POOL[m.group(1)] = [(t, b) for t, b in POOL[m.group(1)]]
load('theory', rd('theory')); load('details', rd('details')); load('checks', rd('appendix_checks'))

head = rd('appendix').split('\\input{sections/appendix_ext}')[0]
main_secs = SEC.split(head)
full = [s for s in main_secs if s.startswith('\\section{Full results tables}')][0]
minimal = [s for s in main_secs if s.startswith('\\section{Minimal Model')][0]
quant = [s for s in main_secs if s.startswith('\\section{Frequentist and Bayesian Quantities')][0]
floats_full = [m.group(0) for m in FLT.finditer(full)]
tab_all = [f for f in floats_full if 'tab:bayes_all' in f][0]
fig_trace = [f for f in floats_full if 'fig:bayes_trace' in f][0]


def take(src, prefix, title=None):
    for t, b in POOL[src]:
        if t.startswith(prefix) and (src, t) not in used:
            used.add((src, t)); return clean(retitle(b, title) if title else b)
    raise KeyError((src, prefix))


def float_block(src):
    """the 'Float(s) Cited in the Main Text' subsection of an ext section: returns its floats only."""
    for t, b in POOL[src]:
        if t.startswith('Float'):
            used.add((src, t)); return ''.join(m.group(0) for m in FLT.finditer(b))
    raise KeyError(src)


def para(text, name):
    m = re.search(r'\\paragraph\{%s\.?\}\s*\n(.*?)(?=\n\\paragraph\{|\n\\input|\Z)' % re.escape(name), text, re.S)
    return m.group(1).strip() + '\n'


def lead(txt): return '\\emph{In short: %s}\n' % txt


def newsub(title, label, lead_txt, body):
    return '\\subsection{%s}\n%s%s%s\n' % (title, ('\\label{%s}\n' % label) if label else '', lead(lead_txt), body)


def section(title, labels, lead_txt, blocks):
    s = '\\section{%s}\n' % title + ''.join('\\label{%s}\n' % l for l in labels) + lead(lead_txt)
    return s + '\n' + '\n'.join(blocks) + '\n\\FloatBarrier\n'



